<?php require_once __DIR__ . '/includes/auth.php'; $user=require_role(['owner','branch_manager','accountant']); $pdo=db(); check_tenant_active($pdo); $tid=require_tenant(); $base=''; $active='reports'; $pageTitle='Reports & Analytics'; $bid=branch_id();
function q1(PDO $pdo,string $sql,array $a){ $s=$pdo->prepare($sql); $s->execute($a); return $s->fetchColumn(); }
function qa(PDO $pdo,string $sql,array $a): array { $s=$pdo->prepare($sql); $s->execute($a); return $s->fetchAll(); }

$from=$_GET['from']??date('Y-m-01'); $to=$_GET['to']??date('Y-m-d');
if (($_GET['export']??'')==='csv') { $rows=qa($pdo,'SELECT order_number,order_type,status,subtotal,discount,tax_amount,total,created_at FROM orders WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? ORDER BY id',[$tid,$from,$to]); export_csv($rows,'sales-report.csv'); }
$daily=qa($pdo,'SELECT DATE(created_at) d, COUNT(*) orders, COALESCE(SUM(total),0) rev FROM orders WHERE tenant_id=? AND status NOT IN ("cancelled","refunded") AND DATE(created_at) BETWEEN ? AND ? GROUP BY DATE(created_at) ORDER BY d',[$tid,$from,$to]);
$monthly=qa($pdo,'SELECT DATE_FORMAT(created_at,"%Y-%b") m, COUNT(*) orders, COALESCE(SUM(total),0) rev FROM orders WHERE tenant_id=? AND status NOT IN ("cancelled","refunded") GROUP BY MONTH(created_at),YEAR(created_at) ORDER BY YEAR(created_at),MONTH(created_at)',[$tid]);
$prodSales=qa($pdo,'SELECT p.name, SUM(oi.quantity) qty, SUM(oi.line_total) rev FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN products p ON p.id=oi.product_id WHERE oi.tenant_id=? AND o.status NOT IN ("cancelled","refunded") AND DATE(o.created_at) BETWEEN ? AND ? GROUP BY p.id ORDER BY rev DESC LIMIT 15',[$tid,$from,$to]);
$payRows=qa($pdo,'SELECT method, COUNT(*) cnt, COALESCE(SUM(amount),0) total FROM order_payments WHERE tenant_id=? AND status="paid" GROUP BY method',[$tid]);
include __DIR__ . '/includes/header.php'; ?>
<form class="row g-2 mb-3" method="get"><div class="col-md-3"><input class="form-control" type="date" name="from" value="<?= e($from) ?>"></div><div class="col-md-3"><input class="form-control" type="date" name="to" value="<?= e($to) ?>"></div><div class="col-md-2"><button class="btn btn-primary w-100">Filter</button></div><div class="col-md-2"><a class="btn btn-outline-success w-100" href="?from=<?= e($from) ?>&to=<?= e($to) ?>&export=csv">Export sales CSV</a></div></form>
<div class="row g-3"><div class="col-lg-6"><div class="card p-3"><h6>Daily sales (selected range)</h6><table class="table table-sm mb-0"><tr><th>Date</th><th>Orders</th><th>Revenue</th></tr><?php foreach($daily as $r): ?><tr><td><?= e($r['d']) ?></td><td><?= $r['orders'] ?></td><td><?= money($r['rev']) ?></td></tr><?php endforeach; if(!$daily) echo '<tr><td colspan="3" class="text-muted">No sales in range.</td></tr>'; ?></table></div>
<div class="card p-3 mt-3"><h6>Monthly sales</h6><canvas id="mChart" height="110"></canvas></div></div>
<div class="col-lg-6"><div class="card p-3"><h6>Product sales</h6><table class="table table-sm mb-0"><tr><th>Product</th><th>Qty</th><th>Revenue</th></tr><?php foreach($prodSales as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= $r['qty'] ?></td><td><?= money($r['rev']) ?></td></tr><?php endforeach; ?></table></div>
<div class="card p-3 mt-3"><h6>Payments by method</h6><table class="table table-sm mb-0"><tr><th>Method</th><th>Payments</th><th>Total</th></tr><?php foreach($payRows as $r): ?><tr><td><?= e($r['method']) ?></td><td><?= $r['cnt'] ?></td><td><?= money($r['total']) ?></td></tr><?php endforeach; ?></table></div></div></div>
<?php $extraJs='<script>makeChart("mChart","line",'.json_encode(array_column($monthly,'m')).','.json_encode(array_map('floatval',array_column($monthly,'rev'))).',"Revenue $");</script>'; include __DIR__ . '/includes/footer.php'; ?>
